"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[97332],{916:(e,i,n)=>{n.r(i),n.d(i,{assets:()=>l,contentTitle:()=>r,default:()=>h,frontMatter:()=>o,metadata:()=>t,toc:()=>c});const t=JSON.parse('{"id":"2023/04/09","title":"2023-04-09","description":"I wish GPT4 had never happened","source":"@site/docs/2023/04/09.md","sourceDirName":"2023/04","slug":"/2023/04/09","permalink":"/th/2023/04/09","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/th/docusaurus-plugin-content-docs//current/2023/04/09.md","tags":[],"version":"current","frontMatter":{"localized_date":"April 9, 2023","top_news":"I wish GPT4 had never happened"},"sidebar":"defaultSidebar","previous":{"title":"2023-04-10","permalink":"/th/2023/04/10"},"next":{"title":"2023-04-08","permalink":"/th/2023/04/08"}}');var s=n(23420),a=n(3331);const o={localized_date:"April 9, 2023",top_news:"I wish GPT4 had never happened"},r="2023-04-09",l={},c=[{value:"I wish GPT4 had never happened",id:"i-wish-gpt4-had-never-happened",level:2},{value:"Why human societies developed so little during 300k years",id:"why-human-societies-developed-so-little-during-300k-years",level:2},{value:"The Garbage Collection Handbook, 2nd Edition",id:"the-garbage-collection-handbook-2nd-edition",level:2},{value:"New Orleans teenagers found a new proof of the Pythagorean Theorem",id:"new-orleans-teenagers-found-a-new-proof-of-the-pythagorean-theorem",level:2},{value:"Do judges give out tougher sentences when hungry? A study too good to be true",id:"do-judges-give-out-tougher-sentences-when-hungry-a-study-too-good-to-be-true",level:2},{value:"Everything advertised on social media is overpriced junk",id:"everything-advertised-on-social-media-is-overpriced-junk",level:2},{value:"Go port of SQLite without CGo",id:"go-port-of-sqlite-without-cgo",level:2},{value:"Why and How We Retired Elm at Culture Amp",id:"why-and-how-we-retired-elm-at-culture-amp",level:2},{value:"FAA K-12 Airport Design Challenge in Minecraft",id:"faa-k-12-airport-design-challenge-in-minecraft",level:2},{value:"Google to Ban Financial Lending Apps from Accessing User Photos, Contacts",id:"google-to-ban-financial-lending-apps-from-accessing-user-photos-contacts",level:2},{value:"Go 1.21 will (likely) have a static toolchain on Linux",id:"go-121-will-likely-have-a-static-toolchain-on-linux",level:2},{value:"Electricity Prices by Country",id:"electricity-prices-by-country",level:2},{value:"0x0: Share Files from Terminal",id:"0x0-share-files-from-terminal",level:2},{value:"Iran installs cameras in public places to identify, penalise unveiled women",id:"iran-installs-cameras-in-public-places-to-identify-penalise-unveiled-women",level:2},{value:"A 1.5GB string",id:"a-15gb-string",level:2},{value:"Paul Graham is an investor in the company trying to kill Twitter",id:"paul-graham-is-an-investor-in-the-company-trying-to-kill-twitter",level:2},{value:"FCC warns Portland church to shut down pirate FM operating under its steeple",id:"fcc-warns-portland-church-to-shut-down-pirate-fm-operating-under-its-steeple",level:2},{value:"GNU+Linux laptops with Libreboot preinstalled, based on coreboot",id:"gnulinux-laptops-with-libreboot-preinstalled-based-on-coreboot",level:2},{value:"Chasing Rainbows: Designing for Colorblindness",id:"chasing-rainbows-designing-for-colorblindness",level:2},{value:"To Supercharge Learning, Look to Play",id:"to-supercharge-learning-look-to-play",level:2},{value:"BrowserBox \u2013 do stuff with browsers that you can&#39;t normally",id:"browserbox--do-stuff-with-browsers-that-you-cant-normally",level:2},{value:"Pydantic V2 rewritten in Rust is 5-50x faster than Pydantic V1",id:"pydantic-v2-rewritten-in-rust-is-5-50x-faster-than-pydantic-v1",level:2},{value:"AI powered realtime fluid simulations are here",id:"ai-powered-realtime-fluid-simulations-are-here",level:2},{value:"Custom Allocators in Rust",id:"custom-allocators-in-rust",level:2},{value:"The Erosion of Free Will: Why Society&#39;s Loss of Belief in Freedom Is Dangerous",id:"the-erosion-of-free-will-why-societys-loss-of-belief-in-freedom-is-dangerous",level:2},{value:"Learn Rust 101 \u2013 A guide to aid your journey of becoming a Rustacean",id:"learn-rust-101--a-guide-to-aid-your-journey-of-becoming-a-rustacean",level:2},{value:"Trashcan \u2013 web based service for indexing scientific papers, or other documents",id:"trashcan--web-based-service-for-indexing-scientific-papers-or-other-documents",level:2},{value:"Spotify streaming GDPR dump local analyzer",id:"spotify-streaming-gdpr-dump-local-analyzer",level:2},{value:"Hacking Google ReCAPTCHA v3 Using Reinforcement Learning (2019)",id:"hacking-google-recaptcha-v3-using-reinforcement-learning-2019",level:2},{value:"Ex-S.F. fire commissioner with fractured skull after metal pipe attack",id:"ex-sf-fire-commissioner-with-fractured-skull-after-metal-pipe-attack",level:2}];function d(e){const i={a:"a",h1:"h1",h2:"h2",header:"header",p:"p",...(0,a.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(i.header,{children:(0,s.jsx)(i.h1,{id:"2023-04-09",children:"2023-04-09"})}),"\n",(0,s.jsx)(i.h2,{id:"i-wish-gpt4-had-never-happened",children:"I wish GPT4 had never happened"}),"\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.a,{href:"https://chaudhry.notion.site/I-wish-GPT4-had-never-happened-9f0cbf2848a44ec9911c07fb34ff5de3",children:"Original"}),".\nN/A."]}),"\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35492730",children:"Discussion Service"}),".\nAn article on the negative impact of GPT-4 gains attention with a mix of opinions on taxation, productivity, socioeconomic classes, and government regulation. A mass professional shift is happening, causing social turmoil, but some argue it opens opportunities for technical skills. Wealth distribution and ownership in a free society are debated, with some arguing for a new solution to AI's adoption downsides. ChatGPT helps users feel more confident with programming languages, but concerns about AI-generated code's increased likelihood of bugs are expressed. GPT-4 is deemed a powerful productivity tool with the potential to replace developers in certain areas. AI's impact on society and the workforce is not yet clear, but AI is not intended to replace human skill and judgment."]}),"\n",(0,s.jsx)(i.h2,{id:"why-human-societies-developed-so-little-during-300k-years",children:"Why human societies developed so little during 300k years"}),"\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.a,{href:"https://woodfromeden.substack.com/p/violent-enough-to-stand-still",children:"Original"}),".\nThe article discusses anthropologist Napoleon Chagnon's findings on Yanomam\xf6 warfare and their unique cultural practices that kept populations down while having abundant resources. The article sheds light on pre-Malthusian societies and how humans have existed in a state of population equilibrium. Human development is episodic, and the question arises, what made human males abandon the zero-sum game and develop more complex societies? The article suggests a new perspective on human history and the evolution of civilization, and comments bring in diverse perspectives, including Marxist views on war in primitive societies."]}),"\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35492591",children:"Discussion Service"}),".\nDiscussion on why human societies stagnated for 300,000 years, with varying perspectives on the role of technology, population growth, and literacy. Some users point out the importance of specific knowledge in fields like engineering and mathematics. A conversation on the development of societies challenges the author's premise and highlights the need to consider societal and cultural factors beyond material technology. The Tech Times report aims to provide concise, unbiased insights for experts in the field. Stay neutral and focus on key points that interest readers, avoiding political or religious statements."]}),"\n",(0,s.jsx)(i.h2,{id:"the-garbage-collection-handbook-2nd-edition",children:"The Garbage Collection Handbook, 2nd Edition"}),"\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.a,{href:"https://www.routledge.com/The-Garbage-Collection-Handbook-The-Art-of-Automatic-Memory-Management/Jones-Hosking-Moss/p/book/9781032218038",children:"Original"}),".\nThe Garbage Collection Handbook, 2nd Edition updates the state of automatic memory management research and development, with a focus on the latest advanced techniques, like parallel, incremental, concurrent, and real-time garbage collection, and their implications for garbage collector designers and implementers. The text also delves into new challenges posed by recent hardware and software advances. This comprehensive guide is primarily intended for memory management researchers and developers seeking insight into different memory management algorithms and designs."]}),"\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35492307",children:"Discussion Service"}),".\n'The Garbage Collection Handbook, 2nd Edition' released, featuring info on Concurrent copying/compaction GC and page fault handling. Userfaultfd and linear logic noted. Debate on GC in Java/Ada, tracing GC and reference counting connectors. Importance of minimizing heap memory allocation discussed. Real-time and non-real-time GCs exist. Some users feel GC is essential, while others prefer manual memory management. Language design expertise \u2260 computer science expertise. Discussion on value types in Swift and sarcasm about garbage collection book in Rust."]}),"\n",(0,s.jsx)(i.h2,{id:"new-orleans-teenagers-found-a-new-proof-of-the-pythagorean-theorem",children:"New Orleans teenagers found a new proof of the Pythagorean Theorem"}),"\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.a,{href:"https://keith-mcnulty.medium.com/heres-how-two-new-orleans-teenagers-found-a-new-proof-of-the-pythagorean-theorem-b4f6e7e9ea2d",children:"Original"}),".\nTwo teenage girls have presented a new proof of the Pythagorean Theorem to the American Mathematical Society, creating quite a stir. This exemplary example proves how open elemental math is to everyone and may encourage others to explore mathematics."]}),"\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35497696",children:"Discussion Service"}),".\nNew Orleans teenagers discovered novel Pythagorean Theorem proof based on Law of Sines. Experts share differing opinions. The two female African-American students presented their work to the American Mathematical Society. Proof uses infinite series of nested triangles and trigonometry conventions. Some users suggest alternative ways to prove theorem. Underrepresented group's achievement and parent involvement debated. Proof only needs to be logically correct. High school students' accomplishment subject to intense scrutiny by experienced mathematicians. Proof not new, but the simplest and most beautiful trigonometric proof to date. Importance of creativity and originality highlighted. YC Summer 2023 applications open."]}),"\n",(0,s.jsx)(i.h2,{id:"do-judges-give-out-tougher-sentences-when-hungry-a-study-too-good-to-be-true",children:"Do judges give out tougher sentences when hungry? A study too good to be true"}),"\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.a,{href:"https://inews.co.uk/news/do-judges-give-out-tougher-sentences-when-hungry-the-story-behind-a-study-too-good-to-be-true-2238347",children:"Original"}),".\nN/A."]}),"\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35491060",children:"Discussion Service"}),".\nA study suggesting that judges give harsher sentences when hungry is disputed, citing experiences with fasting. Religious fasting could actually benefit judges' judgment, while short Ramadan fasts are not comparable to longer ones. Fasting experiences and opinions vary, with some noting clearness and productivity. Studies show positive correlations between cognitive performance and fasting or restricted carbohydrate diets, but more research is needed. Judges fasting during Ramadan in Pakistan were more likely to acquit defendants by 10% each additional hour fasted, but small sample size and scheduling biases were noted. Scientific studies on social phenomena are unreliable and open to differing interpretations, based on comments. The nature of science and the importance of shared truth in scientific discourse were also discussed."]}),"\n",(0,s.jsx)(i.h2,{id:"everything-advertised-on-social-media-is-overpriced-junk",children:"Everything advertised on social media is overpriced junk"}),"\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.a,{href:"https://pluralistic.net/2023/04/08/late-stage-sea-monkeys/#jeremys-razors",children:"Original"}),".\nA study by Carnegie Mellon and Pamplin College found that targeted ads on social media cost an average of 10% more and come from vendors with poor ratings, leading the study to conclude that all advertised products on social media are overpriced junk. Contextual ads perform as well and have better control over creative content. Legislative action is needed to implement an opt-in consent policy for data collection, and to regulate the ad-tech market. A federal privacy law could prevent spying by social media giants and foster competition in app stores, allowing media outlets to earn more revenue. Shifting control from Big Tech can benefit the media at large."]}),"\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35492672",children:"Discussion Service"}),".\nAn article claims that social media advertisements sell overpriced junk, countered by views on benefits including enabling small businesses to advertise for less money. The article focuses on razor market and niche products. Suggestions are made for high-quality products, brand research and regulation of advertising. Product advertising and reviews' limitations are discussed, and the decline in product quality is a common issue. Some point out that newer growth-focused brands may offer better deals. Problems with targeted advertising, lunar topography products, and a delivered scam are experienced."]}),"\n",(0,s.jsx)(i.h2,{id:"go-port-of-sqlite-without-cgo",children:"Go port of SQLite without CGo"}),"\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.a,{href:"https://gitlab.com/cznic/sqlite",children:"Original"}),".\nN/A."]}),"\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35488980",children:"Discussion Service"}),".\nA Go port of SQLite without CGo for cross-compiling is discussed on Discussion Service, with alternatives suggested. Concerns about stability and transaction behavior are raised, with some recommending the C library. There is debate about implementing SQLite in Go, and the benefits of Go-sqlite over standard drivers. The main advantage of Go-sqlite is not using CGO, with developed methods using C to Go compiler for SQLite. Some praise the method, while others report transaction lock errors. An alternative approach using Wasm is recommended."]}),"\n",(0,s.jsx)(i.h2,{id:"why-and-how-we-retired-elm-at-culture-amp",children:"Why and How We Retired Elm at Culture Amp"}),"\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.a,{href:"https://kevinyank.com/posts/on-endings-why-how-we-retired-elm-at-culture-amp/",children:"Original"}),".\nCulture Amp has retired Elm as its preferred language for new front-end code after four years despite its previous promotion by the company's engineering lead. The move was due to an attempt by Culture Amp's design team to build a language-agnostic library of reusable user interface components with Web Components, which demands its framework. Culture Amp chose to stick with React due to its acquisition of a company with an entirely React code base and TypeScript's ability to match Elm's state management. Culture Amp's decision reflects an increasing trend towards selecting React in TypeScript for new projects, and Elm may move from \"adopt\" to \"contain\" status on their Tech Radar. Engineers supported the decision to contain Elm due to the complexity it creates."]}),"\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35495910",children:"Discussion Service"}),".\nCulture Amp's decision to reject job candidates with a specific language preference sparks discussions on Discussion Service, with some agreeing and others disagreeing. Some users caution against being too zealous about a technology and encourage focusing on actual indicators of expertise. Elm's challenges and decline are discussed, with suggestions for other languages. Discussion Service comments discuss company culture, design systems, and tech stack choices. A former Elm user shares their experience switching to TypeScript, while a company with difficulty maintaining two frameworks decides to phase out Elm. The editor must avoid political or religious statements and capture vital points of interest to tech-savvy readers."]}),"\n",(0,s.jsx)(i.h2,{id:"faa-k-12-airport-design-challenge-in-minecraft",children:"FAA K-12 Airport Design Challenge in Minecraft"}),"\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.a,{href:"https://www.faa.gov/airport-design-challenge",children:"Original"}),".\nThe FAA Science, Technology, Engineering, and Math Aviation and Space Education (STEM AVSED) Program is organizing an Airport Design Challenge in Minecraft for students in grades K-12. This interactive learning and collaboration opportunity covers topics ranging from airport layout, pavement, lighting, and structures, to innovative growth. Participants have the chance to work with FAA aerospace and engineering experts, meet aviation professionals, and engage with other designers. Collaborative work between students, parents, and teachers is performed in a virtual environment, and knowledge check assignments and screenshots of designs are used to provide feedback."]}),"\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35494382",children:"Discussion Service"}),".\nThe FAA hosts an airport design challenge using Minecraft for K-12 students in the US. Users discuss the potential benefits and limitations of Minecraft as an educational and creative tool. Some express concerns over kids' technology use, while others highlight its potential to cultivate later interests. The competition generates interest as a unique combination of Minecraft and aviation design. The post suggests that even airport designers can learn from the creativity of 12-year-old kids. The competition also crowdsources 3D world replicas for infrastructure projects and sparks interest in open-sourcing government infrastructure projects for public contribution. Discussion Service users express positive reactions to Minecraft-inspired projects that stimulate children's growth and learning, such as programming and engineering skills."]}),"\n",(0,s.jsx)(i.h2,{id:"google-to-ban-financial-lending-apps-from-accessing-user-photos-contacts",children:"Google to Ban Financial Lending Apps from Accessing User Photos, Contacts"}),"\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.a,{href:"https://www.pcmag.com/news/google-to-ban-financial-lending-apps-from-accessing-user-photos-contacts",children:"Original"}),".\nGoogle has updated its personal loans policy to prevent apps that offer loans from accessing user contacts or photos. This move is aimed at addressing predatory behaviour from some lenders who harass and intimidate borrowers into paying outstanding debts. In addition to this, it will require country-specific licensing documentation to prove their ability to provide or facilitate personal loans, such as in Pakistan. Such practices have led to debt collectors sending manipulated photos to the friends and family of debtors, resulting in a number of targeted individuals taking their lives in countries such as India and Kenya."]}),"\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35494366",children:"Discussion Service"}),".\nGoogle will ban lending apps from accessing user photos and contacts. Suggestions include a two-pronged approach in the Play Store or presenting fake data when permissions are denied. Secure core architecture promises to eliminate malware. Users complain about too many permissions and misuse of data by loan apps. Call for better regulations or a whitelist for loan app access. Privacy concerns and need for individual sharing of contacts. Need for streamlined media access function. Desktop users lack permissions limits. Alternative app stores could weaken user protections. Unique scam in Kenya. Google bans payday loan ads despite allowing them on the app store."]}),"\n",(0,s.jsx)(i.h2,{id:"go-121-will-likely-have-a-static-toolchain-on-linux",children:"Go 1.21 will (likely) have a static toolchain on Linux"}),"\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.a,{href:"https://utcc.utoronto.ca/~cks/space/blog/programming/Go121LinuxStaticToolchain",children:"Original"}),".\nThe upcoming version of Go 1.21 will have a static toolchain on Linux, which means that the compiler will be built using the pure Go resolver only and will be a static executable, unless the developers revert for some reason. This will allow for a nice quality of life improvement for people who mostly work on recent Linuxes, but who occasionally have to deal with older ones. However, this change will not automatically make user programs version-independent. Currently, elements of the plan have already landed in the Go development version."]}),"\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35490941",children:"Discussion Service"}),".\nGo 1.21 to have faster static toolchain on Linux, but criticisms on handling of nil pointer panics still persist. Some suggest retrofitting features without breaking backwards compatibility, but others argue against generics. Users praise ease of use and toolchain appeal of Go. Rust's borrow checker, memory safety limitations, and lifetimes are also discussed. Go's DNS resolver and reliance on libc debated, with pros and cons of dynamic vs. static linking. DNS lookup implementation on macOS discussed, building client executables in debian squeeze docker container suggested, and using Go for fully reproducible toolchain on 1.21."]}),"\n",(0,s.jsx)(i.h2,{id:"electricity-prices-by-country",children:"Electricity Prices by Country"}),"\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.a,{href:"https://www.electricrate.com/data-center/electricity-prices-by-country/",children:"Original"}),".\nThe article delves into the cost and sources of electricity across countries, revealing how Germany and Bermuda are the most expensive while Sudan, Venezuela, and Iran are the cheapest. Most countries still primarily depend on fossil fuels for electricity generation. Notably, the US has the highest household electricity usage but a similar cost to the global average. Furthermore, 13% of the world's population is still without access to electricity. It's important to consider access and sustainability when analyzing electricity prices, with cheap prices often causing harm to the environment."]}),"\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35495579",children:"Discussion Service"}),'.\nAn article on "Electricity Prices by Country" gains attention on Hacker News, as readers discuss factors such as regional energy usage differences and propane usage in rural areas. Users share their experiences in drastically reducing energy consumption, while others point out flaws in data and express surprise at low energy usage. Regional variations in pricing due to geography and political policies are significant, and prices should be normalized by local average income for a fair comparison. Argentine and Venezuelan subsidies spark concerns, while critics suggest simplistic data comparisons for marketing purposes. Germany\'s high prices are attributed to the cost of natural gas, while Swede and UK prices are cited as not matching on-the-ground costs. The article covers electricity prices in African countries, though commenters note flaws in using averages to describe the entire sample, and the irrelevance of prices without electricity availability.']}),"\n",(0,s.jsx)(i.h2,{id:"0x0-share-files-from-terminal",children:"0x0: Share Files from Terminal"}),"\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.a,{href:"https://0x0.st/",children:"Original"}),".\nOnline file-sharing service 0x0 has been taken offline after German police seized its servers. The shutdown came despite 0x0.st operating a clear\u200b prohibition against illegal file sharing or activity. Anonymous uploads and remote URLs were made available using the platform, which could delete files and set expire dates. The service's operator, named Mia, said hosting costs were \u20ac60 ($65) a month, while adding that the service was blocked to exit nodes due to many rule violations, and that uploaders who violate the site's rules would have their IP address banned. No arrests have been reported to date."]}),"\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35491520",children:"Discussion Service"}),'.\n\'Hacker News\' talks about a file-sharing service for the terminal, and shares legal risks and deterrents. Several alternatives mentioned. Another discussion about file-hosting services, suggested alternatives, but pointed out lack of support for .rar files and uploads related to cryptocurrency. CloudFlare-powered version is also noted. A GitHub page with curl instructions marked "made to look like a crash" and a code snippet with "enhancements" with an opened application for YC Summer 2023.']}),"\n",(0,s.jsx)(i.h2,{id:"iran-installs-cameras-in-public-places-to-identify-penalise-unveiled-women",children:"Iran installs cameras in public places to identify, penalise unveiled women"}),"\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.a,{href:"https://www.reuters.com/world/middle-east/iran-installs-cameras-public-places-identify-penalise-unveiled-women-police-2023-04-08/",children:"Original"}),".\nIran is installing cameras in public places to identify and penalise unveiled women who do not comply with the compulsory dress code. Violators will receive warning text messages as to the consequences after being identified. This move is intended to prevent resistance against the hijab law, which has seen a growing number of Iranian women ditching their veils since the death of a 22-year-old Kurdish woman in custody of morality police last September. The authorities have urged citizens to confront unveiled women, and the statement will require owners of businesses to monitor the observance of societal norms."]}),"\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35494941",children:"Discussion Service"}),".\nIran installs cameras to penalize unveiled women while discussions on individual freedom and religious oppression emerge. Discussion Service users debate on the Iranian government's treatment of women and the use of surveillance technology, drawing parallels to gun control laws and the potential impact of AI-powered cameras. Users argue for personal choice and against coercion, while some discuss issues around migrant communities and women's rights. There are mixed opinions on the issue, and comparisons are made to nazi symbols and tactics used by the US government to quell unrest. The comments raise important questions about surveillance, privacy, and cultural values in shaping its use."]}),"\n",(0,s.jsx)(i.h2,{id:"a-15gb-string",children:"A 1.5GB string"}),"\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.a,{href:"https://blog.backslasher.net/1.5GB-string.html",children:"Original"}),".\nThe author describes how, during their previous role, they discovered a significant memory waste in a Java service they supported. Using capacity planning sessions, they were able to identify memory-wasting objects in the Java memory dump, including a 1.5GB string. They found that it was due to a design problem where they were saving more and more state until it exploded. They divided the problem into a quick fix and a long-term one, rewriting the stack solution for the long-term fix. The author emphasizes the importance of examining the details of how programs use resources to produce quick wins from the start."]}),"\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35496712",children:"Discussion Service"}),".\nThe post discusses optimizing memory, exponential growth, and serialization protocols, with various solutions proposed. User experiences with bad APIs and browser glitches are also shared. Debate on backslasher.net's domain registration ensues. Additional discussions include technicalities on efficient data handling, compressing transmission size, and restructuring data storage. Limiting string length raises issues."]}),"\n",(0,s.jsx)(i.h2,{id:"paul-graham-is-an-investor-in-the-company-trying-to-kill-twitter",children:"Paul Graham is an investor in the company trying to kill Twitter"}),"\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.a,{href:"https://twitter.com/paulg/status/1644635086715858944",children:"Original"}),".\nPaul Graham's investment fund, Y Combinator, invested in a start-up called Tilde, which is working on a decentralized, open-source alternative to Twitter called Mastodon. Mastodon's growth has been steady, with over 1.2 million registered users, but analysts believe it may not pose a significant threat to Twitter due to the lack of monetization options for Mastodon. Some Discussion Service users criticize Graham for investing in a company trying to kill another company, while others defend the principles of competition and innovation."]}),"\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35493046",children:"Discussion Service"}),".\nPaul Graham's investment in Twitter-killing companies sparks discussion on Twitter's future. Profitability and conspiracy theorists are issues for Substack as an alternative. Niche communities may not replace Twitter. Discoverability and network effect are key for social media success. Elon Musk's role in Twitter conflicts with his ideal of a digital public square. Substack just launched \"Substack Notes\", a Twitter clone. Vote and account trading may be happening on the platform. Some like Substack, others on fence. Elon Musk's success with Tesla and SpaceX is attributed to his leadership style. Bad behavior and safety concerns have led some to swear off buying Tesla. The next iteration of social media should be non-profit with explicit content guidelines. Substack expanding into microblogging, concerns Twitter personalities. Twitter attracts hateful content and needs more regulation. Issues with bots have plagued Twitter."]}),"\n",(0,s.jsx)(i.h2,{id:"fcc-warns-portland-church-to-shut-down-pirate-fm-operating-under-its-steeple",children:"FCC warns Portland church to shut down pirate FM operating under its steeple"}),"\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.a,{href:"https://www.insideradio.com/free/fcc-warns-portland-church-to-shut-down-pirate-fm-operating-under-its-steeple/article_f89e2ebc-cf96-11ed-9c83-4b0d056dd422.html",children:"Original"}),".\nThe Federal Communications Commission (FCC) has alerted the Eastside Free Methodist Church, based in Portland, that an unlicensed FM radio station, operating on 90.5 FM, has been identified to be operating under its steeple. Field agents from the FCC tracked the pirate radio but did not find any individuals currently there, and the church maybe closed according to the online postings available. It is probable that the church will face enforcement action under federal law, as it owns the building. Any evidence should be submitted to prove that the pirate radio broadcasting no longer occurs at the premises. The warning letter sent to the church indicates that it will face a penalty worth more than $2.3m in fines."]}),"\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35496871",children:"Discussion Service"}),".\nThe FCC warned a Portland church to shut down a pirate FM radio station under its steeple. Such stations can interfere with emergency communication, and are not part of EAS. However, some consider pirate stations necessary for independent voices. The caught pirate was fined $80,000 and had numerous warnings. Discussion on the regulation, legality, and efficiency of radio use and allocation ensued, with suggestions for LPFM stations. Interference can be caused by the overlap of analogue and digital signals. Some Norway radio enthusiasts are discussing FM pirate stations. Regulations and control over airwaves are contentious topics."]}),"\n",(0,s.jsx)(i.h2,{id:"gnulinux-laptops-with-libreboot-preinstalled-based-on-coreboot",children:"GNU+Linux laptops with Libreboot preinstalled, based on coreboot"}),"\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.a,{href:"https://minifree.org/",children:"Original"}),".\nMinifree Ltd sells GNU+Linux laptops with Libreboot, a BIOS/UEFI replacement based on Coreboot, pre-installed, with encrypted Debian GNU+Linux OS and full driver support; it also offers options for other Linux distros or BSD. It is perfect for privacy software such as Tor Browser or Tails, with 480/960GB SSD, 2x480GB/2x960GB RAID1 SSD, good battery, and 16GB RAM. The company provides free technical support via email and IRC, plus a five-year warranty, funding Libreboot development. The recent major Libreboot release, version 20230319, is now available from Minifree, which installs the latest version by default."]}),"\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35496651",children:"Discussion Service"}),".\nMinifree offers GNU+Linux laptops with Libreboot preinstalled based on coreboot. T440p model provides open-source BIOS and OS control, but requires technical knowledge. System76 has better hardware but less choice. Flashing Coreboot is difficult on some hardware. Debate over Intel Management Engine's security risk. GNU's importance to Linux users outweighs GNU quoting error. Some point out systemd is not a GNU project."]}),"\n",(0,s.jsx)(i.h2,{id:"chasing-rainbows-designing-for-colorblindness",children:"Chasing Rainbows: Designing for Colorblindness"}),"\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.a,{href:"https://www.theverge.com/23650428/colorblindness-design-ui-accessibility-wordle",children:"Original"}),'.\n"The Verge" article discusses designing for colorblindness and calls attention to the fact that the world was not designed for people with colorblindness. Around 350 million people globally are colorblind, and about 8% of men have some form of color vision deficiency. Practical examples are provided to demonstrate the difficulties colorblind people face, and the article emphasizes the importance of accessibility in design as a way of empathy.']}),"\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35489168",children:"Discussion Service"}),".\nDesigners must not rely on color alone; contrasts and shapes are vital for colorblind users. Better design can accommodate colorblindness as an aspect of universal design. Brightness, contrast, labels, icons, and textures help distinguish colors. Consider shapes or font to distinguish elements. Automated accessibility testing available. Colorblindness reduces only the ability to differentiate hues. Discussion on individual colorblindness and perception of traffic lights. Some frequencies in green are difficult to see. Walk signs appear white to some, but green to others with colorblindness."]}),"\n",(0,s.jsx)(i.h2,{id:"to-supercharge-learning-look-to-play",children:"To Supercharge Learning, Look to Play"}),"\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.a,{href:"https://nautil.us/to-supercharge-learning-look-to-play-292946/",children:"Original"}),".\nPlay and the arts are vital for learning, building the '6 C's' of collaboration, communication, content, critical thinking, creative innovation, and confidence. Playful Learning Landscapes Action Network integrates play into public places, promoting intergenerational and peer-to-peer learning. Immersive video games, designed with neuroarts in mind, can boost attention, particularly for those with ADHD. NeuroRacer, an immersive video game designed by Adam Gazzaley, successfully improved cognitive control and attention abilities in clinical trials for children with ADHD. Now, known as EndeavorRx, it's the first non-drug treatment for ADHD, approved by the FDA in 2020. Adam's work emphasizes the intersection of arts and sciences to address learning differences."]}),"\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35494342",children:"Discussion Service"}),".\nAn Discussion Service user suggests AI-based learning could alleviate stress in California education, but others blame bureaucratic mismanagement. AI's impact on education is debated, with concerns about socialization, discipline, and teacher guidance. Playful methodologies in learning, particularly for ADHD, are discussed, with personal experiences shared and resources provided."]}),"\n",(0,s.jsx)(i.h2,{id:"browserbox--do-stuff-with-browsers-that-you-cant-normally",children:"BrowserBox \u2013 do stuff with browsers that you can't normally"}),"\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.a,{href:"https://github.com/dosyago/BrowserBox",children:"Original"}),".\nBrowserBox is a remote, isolated browser API that can be run on the cloud or self-hosted, with a regular and Pro version available. The Pro version has more advanced features, frequently updated and embeds directly into a web page, while the regular version has a slower release cycle. Both versions offer unrestricted browser capabilities, multi-tab, mobile-ready browser UI frontend, co-browsing, adaptive streaming, and secure document viewing. BB Pro is highly secure and features a range of security measures like RBI browser isolation security model and built-in AdBlocker, and the software is available under the Polyform Shield License 1.0.0."]}),"\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35490289",children:"Discussion Service"}),".\nBrowserBox gains attention on Hacker News, allowing users to access inaccessible files/codes. Solutions offered, including localhost server and browser extension. License history questioned, pricing a concern. Cloudflare's S2 mentioned as alternative for isolation. Dosy Browser provides indirect rendering of websites using Chrome. Alternative implementations suggested. Dosy Browser's non-commercial use license discussed. Opera Mini's device support and data compression reminisced. BrowserBox acts as a client-server app via automation protocol, enabling internet browsing on older tech devices. Pricing info found on individual.dosyago.com."]}),"\n",(0,s.jsx)(i.h2,{id:"pydantic-v2-rewritten-in-rust-is-5-50x-faster-than-pydantic-v1",children:"Pydantic V2 rewritten in Rust is 5-50x faster than Pydantic V1"}),"\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.a,{href:"https://docs.pydantic.dev/blog/pydantic-v2-alpha/",children:"Original"}),".\nPydantic V2, with a rewritten pydantic-core, is 5-50x faster and more maintainable than Pydantic V1. The library offers parsing and validation capabilities, serialization, setting management, and recursive data structure validation, along with JSON schema generation, custom types, and field validators. The alpha is open to evaluation and experimentation in testing environments, with feedback for further development. Pydantic V2 has an AnalyzedType class for easy validation and serialization of non-BaseModel objects, changes to Validation, and the removal of GetterDict. The API is provisional and subject to change."]}),"\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35490449",children:"Discussion Service"}),".\nPydantic V2 rewritten in Rust allows a 5-50x performance increase compared to V1. Rust has challenges with different platform binaries. Drop-in replacement library with minor API changes. Some users criticize Python's lack of optimization strategy, while others appreciate its ease for scientists. Python community's declining code quality is acknowledged. Pydantic V2 praised for features, but criticized for reliance on Rust. Some users suggest alternatives like msgspec."]}),"\n",(0,s.jsx)(i.h2,{id:"ai-powered-realtime-fluid-simulations-are-here",children:"AI powered realtime fluid simulations are here"}),"\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.a,{href:"https://echoesofsomewhere.com/2023/04/06/ai-fluid-simulations/",children:"Original"}),".\nA developer tested an AI-powered fluid simulation tool for adding realistic, interactive smoke to a game, comparing EmberGen and Zibra Smoke & Fire. The AI-powered tool proved to work well and was more efficient than baking fluid animations as flip-books. The Zibra tool is 3D, making the smoke blend better with the environment and has impressive performance, running smoothly on an iPhone. The tool uses an AI-powered acceleration concept and compact SDF for object shape representation. The simulation render added about 2 ms to frame times. The tool has some control settings for the smoke's appearance, such as absorption, scattering, and shadow colors."]}),"\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35490533",children:"Discussion Service"}),".\nReal-time fluid simulations with AI are 15x faster than alternatives, using neural networks to mimic physics. Some Discussion Service users question use of physics-informed neural networks for fluid dynamics. AI may have potential for scientific thermodynamic simulations. Unclear what AI specifically does in the simulation. AI uses dimensionality reduction due to curse of dimensionality. Probability of physical accuracy in games simulations is low. Open source CFD software (OpenFOAM) available, but site is down."]}),"\n",(0,s.jsx)(i.h2,{id:"custom-allocators-in-rust",children:"Custom Allocators in Rust"}),"\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.a,{href:"https://nical.github.io/posts/rust-custom-allocators.html",children:"Original"}),".\nNicalIndex discusses custom allocators in Rust for improved memory allocation strategies, enabling different parts of a program to choose strategies. Rust has a default global allocator, with two proposals for custom allocator support. The article explores approaches to custom allocators in Rust data structures, focusing on the fill tessellator implementation in the lyon library. Different approaches involve lifetime parameters, two structures, or a manually managed trait object. Adding custom allocators is easy and should utilize the Allocator trait for the best abstraction. Recycling allocations and choosing the right allocator for specific code parts are options for developers. The Allocator trait must be stabilized for Storage implementations to leverage it."]}),"\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35491936",children:"Discussion Service"}),".\nRust may support dynamic scoping for custom allocators despite the unsafe API challenge. Efforts are being made to combine custom allocators with Rust's 'std' types. The 'big box' issue in allocator API requires safer custom allocation handling in Rust. Passing containers and lifetime annotations can solve Rust's default allocation problem. Lifetime system may enhance library design but not optimization. A user seeks input on custom allocators for tensor operations."]}),"\n",(0,s.jsx)(i.h2,{id:"the-erosion-of-free-will-why-societys-loss-of-belief-in-freedom-is-dangerous",children:"The Erosion of Free Will: Why Society's Loss of Belief in Freedom Is Dangerous"}),"\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.a,{href:"https://read.lukeburgis.com/p/the-erosion-of-free-will-why-societys",children:"Original"}),".\nLuke Burgis argues that the erosion of society's belief in freedom and free will is becoming increasingly dangerous, especially in Silicon Valley, and has ethical implications for political systems and human behavior. Burgis proposes a new framework for understanding freedom, one that involves physical, psychological, and spiritual aspects with twelve distinct moments. By achieving integrity, Burgis believes that free will can be saved, without which love in society cannot exist."]}),"\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35489807",children:"Discussion Service"}),".\nAn article on Discussion Service discusses society's erosion of belief in freedom. Comments challenge author's claims and criticize simplification of complex issues. The concept of free will is debated with some arguing it does not exist fundamentally. No consensus in Judeo-Christian traditions on free will importance. Some comments accuse the article of ignoring the influence of religions on free will. Y Combinator post provides guidelines for Summer 2023 program, catering to startup companies. Valuable information for tech-savvy readers, advised to avoid dull facts and maintain neutrality."]}),"\n",(0,s.jsx)(i.h2,{id:"learn-rust-101--a-guide-to-aid-your-journey-of-becoming-a-rustacean",children:"Learn Rust 101 \u2013 A guide to aid your journey of becoming a Rustacean"}),"\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.a,{href:"https://github.com/plabayo/learn-rust-101/blob/main/README.md",children:"Original"}),'.\nThe "learn-rust-101" guide on GitHub is a comprehensive resource for learning Rust, a popular programming language, with milestones for learning various concepts. Other resources include Rustlings, Programming Rust, and the book "Code like a pro in Rust". Readers are encouraged to apply knowledge through optional projects or contributing to open-source projects. The article also includes information on using Rust for WebAssembly, native apps, and web programming, as well as resources for continuous learning. Deno is suggested as a more secure alternative to NodeJS, and the Rust community offers various free resources.']}),"\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35489029",children:"Discussion Service"}),".\nA guide for learning Rust with a focus on general Rust, not just web development. Rust is a great choice for products requiring backends, 3D graphics APIs, and interaction with low-level OS APIs. Rust performs better than Go or Python on GCP cloud runs, with lower memory usage and fast execution. The 'learn by porting' approach is a great way to learn Rust; there are no good walkthroughs for the approach currently."]}),"\n",(0,s.jsx)(i.h2,{id:"trashcan--web-based-service-for-indexing-scientific-papers-or-other-documents",children:"Trashcan \u2013 web based service for indexing scientific papers, or other documents"}),"\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.a,{href:"https://gitlab.com/mildlyparallel/trashcan",children:"Original"}),".\nN/A."]}),"\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35492067",children:"Discussion Service"}),".\nA web-based service for indexing scientific papers and documents is discussed with favorable reviews, and some mention comparable services such as I, Librarian and Paperless-ngx, however, the service falls short in automatic metadata retrieval and citation creation capabilities."]}),"\n",(0,s.jsx)(i.h2,{id:"spotify-streaming-gdpr-dump-local-analyzer",children:"Spotify streaming GDPR dump local analyzer"}),"\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.a,{href:"https://github.com/pldubouilh/spotify-gdpr-dump-analysis",children:"Original"}),".\nN/A."]}),"\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35492137",children:"Discussion Service"}),".\nA new Spotify streaming GDPR dump local analyzer has been created, allowing users to analyze their own data. Users can request an export of their data and then analyze it using the tool. While some users are excited about this, others find it creepy that Spotify tracks mood and location data. Several comments on the thread digress from the main point of the article, but there are requests for more tools like this to make sense of GDPR dumps."]}),"\n",(0,s.jsx)(i.h2,{id:"hacking-google-recaptcha-v3-using-reinforcement-learning-2019",children:"Hacking Google ReCAPTCHA v3 Using Reinforcement Learning (2019)"}),"\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.a,{href:"https://arxiv.org/abs/1903.01003",children:"Original"}),".\nResearchers have developed a reinforcement learning methodology to bypass Google's reCAPTCHA v3. In formulating the problem as a grid world, the agents can learn how to move the mouse and click on the reCAPTCHA button to receive a high score, which means the methodology uses a divide and conquer strategy to defeat this captcha system for any grid resolution. The proposed method achieves a success rate of 97.4% on a 100x100 grid and 96.7% on a 1000x1000 screen resolution. The authors also show that increasing the cell size reduces the performance of the agent."]}),"\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35489342",children:"Discussion Service"}),".\nA new article details a Reinforcement Learning method to bypass ReCAPTCHA v3. Comments discuss the lack of added value for current systems and past experiences with accessibility options. Some users suggest alternatives to solving captchas, while others question how the more difficult captchas align with accessibility legislation. The paper may not hold up without validation, and the lack of critical details is noted."]}),"\n",(0,s.jsx)(i.h2,{id:"ex-sf-fire-commissioner-with-fractured-skull-after-metal-pipe-attack",children:"Ex-S.F. fire commissioner with fractured skull after metal pipe attack"}),"\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.a,{href:"https://www.sfchronicle.com/bayarea/article/marina-sf-crime-attack-fire-commissioner-17883532.php",children:"Original"}),".\nFormer San Francisco fire commissioner, Don Carmignani, was hospitalized with a fractured skull and 51 stitches after being attacked with a metal object while leaving his mother's house in the Marina District. Authorities have arrested a man for the alleged assault. His friend, Joe Alioto Veronese, claimed that Carmignani was beaten by three men who lived in a nearby homeless neighborhood. Veronese speculates that the attack might have been retribution for a phone call Carmignani made on Tuesday when he requested that police remove loiterers in front of his mother's home. The incident has raised concerns about safety in the city."]}),"\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35489067",children:"Discussion Service"}),".\nAn ex-SF fire commissioner was attacked, sparking discussion on SF's crime problem and law enforcement. Users suggest stricter law enforcement and at-large elections. Social services are deemed insufficient, and gun laws are debated. Lack of government and public safety, and desensitization of people, are identified as causes, and starting points for change. Political will and dogma are obstacles, with speculation that fund aid could be indirectly hurting combatting crime. The conversation revolves around solutions to SF's issues, Second Amendment and gun control, and citizens being informed of rights and responsibilities."]})]})}function h(e={}){const{wrapper:i}={...(0,a.R)(),...e.components};return i?(0,s.jsx)(i,{...e,children:(0,s.jsx)(d,{...e})}):d(e)}},3331:(e,i,n)=>{n.d(i,{R:()=>o,x:()=>r});var t=n(36672);const s={},a=t.createContext(s);function o(e){const i=t.useContext(a);return t.useMemo((function(){return"function"==typeof e?e(i):{...i,...e}}),[i,e])}function r(e){let i;return i=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:o(e.components),t.createElement(a.Provider,{value:i},e.children)}}}]);